//! Envelopes and a record exactly as the client writes them, in the listings
//! format of darwin-listings v0.2.1 (commit 381d7c1). They were generated once
//! from that release under its own Cargo.lock (rmp-serde 1.3.1, `self_encryption`
//! 0.36.0, postcard 1.1.3), and darwin-client pins the same literals, so a
//! change to the format on either side, or in a dependency that encodes it,
//! fails a test rather than leaving nodes unable to read what clients store.
//!
//! The inputs: the data map [`data_map`] (three chunks, 11,999 bytes), the
//! same chunks as a child map ([`child_map`]), the salt [`SALT`], and the
//! metadata [`metadata`]. The envelopes are what an upload stores for
//! `EnvelopeOptions::private()`, `unlisted()` and `listed()` with that
//! metadata, every payment field shown:
//!
//! - private: `Envelope::withheld(&data_map(), &SALT, metadata(), ShownFields::ALL, false)`;
//! - unlisted: `Envelope::readable(&data_map(), metadata(), ShownFields::ALL, false)`;
//! - listed: `Envelope::readable(&data_map(), metadata(), ShownFields::ALL, true)`.
//!
//! [`PRIVATE_RECORD`] is the `.record` file a private upload saves, without
//! its final newline: the proof of the private envelope, paid in transaction
//! [`PRIVATE_RECORD_TX`] with a quote signed by a key made for it, revealing
//! the data map and the salt.

use ant_listings::self_encryption::{ChunkInfo, DataMap, XorName};
use ant_listings::Metadata;

/// The chunks of [`data_map`] and [`child_map`].
fn infos() -> Vec<ChunkInfo> {
    [
        (0x11, 0x21, 4_000),
        (0x12, 0x22, 4_000),
        (0x13, 0x23, 3_999),
    ]
    .into_iter()
    .enumerate()
    .map(|(index, (dst, src, src_size))| ChunkInfo {
        index,
        dst_hash: XorName([dst; 32]),
        src_hash: XorName([src; 32]),
        src_size,
    })
    .collect()
}

/// The file's data map.
pub fn data_map() -> DataMap {
    DataMap::new(infos())
}

/// The same chunks as a child map, as a shrunk data map is stored.
pub fn child_map() -> DataMap {
    DataMap::with_child(infos(), 1)
}

/// The envelopes' metadata.
pub fn metadata() -> Metadata {
    Metadata {
        content_type: Some("text/plain".to_string()),
        name: Some("notes.txt".to_string()),
    }
}

/// The salt of the private envelope.
pub const SALT: [u8; 32] = [3; 32];

/// `encode_data_map(&data_map())`, hex.
pub const DATA_MAP: &str = "";

/// `encode_data_map(&child_map())`, hex.
pub const CHILD_MAP: &str = "";

/// `salted_hash(&SALT, DATA_MAP)`, hex: what the private envelope carries.
pub const SALTED_HASH: &str = "2ab61dabaca72a3eaf12dfc1061b0f3309a612f21019e0e62db97bedc8171ed8";

/// The private envelope, hex.
pub const PRIVATE_ENVELOPE: &str = "00414e544c495354025f0a746578742f706c61696e096e6f7465732e7478742ab61dabaca72a3eaf12dfc1061b0f3309a612f21019e0e62db97bedc8171ed8";

/// Its address, hex.
pub const PRIVATE_ADDRESS: &str =
    "1caad8d4d502ecdbe32032fd674b6092b83c9b6caa2c0e43fa93c82d81826191";

/// The unlisted envelope, hex.
pub const UNLISTED_ENVELOPE: &str = "";

/// Its address, hex.
pub const UNLISTED_ADDRESS: &str =
    "d994f77c1e68e705416e63ef3f830225f1b19d1236e8729768f8b5d70ab7130a";

/// The listed envelope, hex.
pub const LISTED_ENVELOPE: &str = "";

/// Its address, hex.
pub const LISTED_ADDRESS: &str = "29f14ad2b6037dbc576c7c1a2ade9ace807262bac6cbe1c7bbf9422ff3e62121";

/// The transaction [`PRIVATE_RECORD`] names.
pub const PRIVATE_RECORD_TX: [u8; 32] = [0x5a; 32];

/// The private upload's `.record`, without its final newline.
pub const PRIVATE_RECORD: &str = "";
